const d = $input.first().json;
const wfNome = (d.workflow && d.workflow.name) || '?';
const ex = d.execution || {};
const err = ex.error || (d.trigger && d.trigger.error) || {};
const no = ex.lastNodeExecuted || (err.node && err.node.name) || '?';
const msg = String(err.message || err.description || 'sem detalhe').slice(0, 400);
// no máximo 1 alerta do mesmo erro a cada 30 min
const st = $getWorkflowStaticData('global');
const chave = wfNome + '|' + no + '|' + msg.slice(0, 80);
const agora = Date.now();
st.vistos = Object.fromEntries(Object.entries(st.vistos || {}).filter(([, t]) => agora - t < 30 * 60 * 1000));
if (st.vistos[chave]) return [];
st.vistos[chave] = agora;
const hora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
return [{ json: { texto: '🚨 *Robô da Ana — erro*\n\nFluxo: ' + wfNome + '\nEtapa: ' + no + '\nQuando: ' + hora + '\n\nErro: ' + msg + (ex.id ? '\n\nExecução nº ' + ex.id + ' (veja em Executions no n8n)' : '') } }];
